package com.pandinila.broadband_management.controller;import com.pandinila.broadband_management.entity.*;import com.pandinila.broadband_management.repository.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/teams") public class TeamController {private final SupportTeamRepository teams;private final EngineerRepository engineers;public TeamController(SupportTeamRepository t,EngineerRepository e){teams=t;engineers=e;}@GetMapping public List<SupportTeam> all(){return teams.findAll();}@GetMapping("/{id}") public SupportTeam one(@PathVariable Long id){return teams.findById(id).orElseThrow();}@GetMapping("/{id}/engineers") public List<Engineer> engineers(@PathVariable Long id){return engineers.findByTeamId(id);}}
